// Social-Pip LinkedIn Pre-Publish Check
// LinkedIn is the MOST restrictive - professional platform
const item = $input.first().json;

const LINKEDIN_MAX_DAILY = 3;
const LINKEDIN_MIN_DELAY_MS = 60 * 60 * 1000; // 60 minutes (longest)
const LINKEDIN_MAX_CHARS = 1300;
const LINKEDIN_MAX_HASHTAGS = 5;

const accountStats = {
  postsToday: item.postsToday || 0,
  lastPostAt: item.lastPostAt ? new Date(item.lastPostAt) : null,
  accountStatus: item.accountStatus || 'ACTIVE'
};

const errors = [];

// LinkedIn has the strictest daily limit
if (accountStats.postsToday >= LINKEDIN_MAX_DAILY) {
  errors.push(`Daily limit reached: ${accountStats.postsToday}/${LINKEDIN_MAX_DAILY}`);
}

// Longest delay requirement
if (accountStats.lastPostAt) {
  const timeSinceLastPost = Date.now() - accountStats.lastPostAt.getTime();
  if (timeSinceLastPost < LINKEDIN_MIN_DELAY_MS) {
    const waitMinutes = Math.ceil((LINKEDIN_MIN_DELAY_MS - timeSinceLastPost) / 60000);
    errors.push(`Wait ${waitMinutes} more minutes before next post.`);
  }
}

// LinkedIn-specific content checks
if (item.content) {
  if (item.content.length > LINKEDIN_MAX_CHARS) {
    errors.push(`Content too long: ${item.content.length}/${LINKEDIN_MAX_CHARS}`);
  }

  const hashtags = (item.content.match(/#/g) || []).length;
  if (hashtags > LINKEDIN_MAX_HASHTAGS) {
    errors.push(`Too many hashtags: ${hashtags}/${LINKEDIN_MAX_HASHTAGS} (LinkedIn recommends 3-5)`);
  }

  // Check for professional tone
  const unprofessionalWords = ['amazing', 'incredible', 'awesome', 'lol', 'omg'];
  const contentLower = item.content.toLowerCase();
  const foundUnprofessional = unprofessionalWords.filter(w => contentLower.includes(w));
  if (foundUnprofessional.length > 0) {
    errors.push(`Consider more professional tone. Found: ${foundUnprofessional.join(', ')}`);
  }
}

// Check account status
if (['BANNED', 'RESTRICTED', 'SUSPENDED'].includes(accountStats.accountStatus)) {
  errors.push(`Account status: ${accountStats.accountStatus}`);
}

if (errors.length > 0) {
  return { json: { valid: false, errors, accountStats } };
}

return { json: { valid: true, post: item, accountStats } };

const result = $input.first().json;

if (result.error) {
  return {
    json: {
      success: false,
      error: result.error,
      errorCode: result.errorCode || 'UNKNOWN',
      platform: 'linkedin'
    }
  };
}

return {
  json: {
    success: true,
    postId: result.id,
    postUrl: `https://linkedin.com/posts/${result.id}`,
    publishedAt: new Date().toISOString(),
    platform: 'linkedin'
  }
};

